(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const $$ = s => [...document.querySelectorAll(s)];
  const volumes=[1000,2500,5000,10000,20000,30000,50000,75000,100000,150000,200000,300000];
  let period='month';
  const money=value=>'$'+Math.round(value).toLocaleString('en-US');
  function calculate(volume,seats,period){const rate=volume<10000?10:volume<50000?9.3:volume<100000?8:7;const creditSeats=Math.ceil(volume/1000),needed=Math.max(seats,Math.min(creditSeats,20)),us=volume/1000*rate,apollo=needed*149,zoom=(15000+Math.max(0,needed-3)*2500)/12,mult=period==='year'?12:1;return{us:us*mult,apollo:apollo*mult,zoom:zoom*mult,savings:Math.max(0,Math.min(apollo,zoom)-us)*12,from:creditSeats>20||seats>20};}
  function renderCalculator(){const index=Number($('#volume').value),volume=volumes[index];let seats=Number($('#seats').value);if(!Number.isFinite(seats)||seats<1)seats=1;seats=Math.min(100,Math.round(seats));const result=calculate(volume,seats,period);$('#volume-label').textContent=volume.toLocaleString('en-US');$('#volume').setAttribute('aria-valuetext',volume.toLocaleString('en-US')+' leads per month');$('#cost-us').textContent=money(result.us);$('#cost-apollo').textContent=(result.from?'from ':'')+money(result.apollo);$('#cost-zoom').textContent=(result.from?'from ':'')+money(result.zoom);$('#savings').textContent=money(result.savings);const max=Math.max(result.us,result.apollo,result.zoom);['us','apollo','zoom'].forEach(key=>$('#bar-'+key).style.width=Math.max(4,result[key]/max*100)+'%');$$('[data-volume]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.volume)===volume)));return{volume,period,cleanRows:money(result.us),apolloEstimate:$('#cost-apollo').textContent,zoomInfoEstimate:$('#cost-zoom').textContent,annualSavings:money(result.savings)};}
  $('#volume').addEventListener('input',renderCalculator);$('#seats').addEventListener('input',renderCalculator);$('#seats').addEventListener('change',()=>{$('#seats').value=String(Math.max(1,Math.min(100,Math.round(Number($('#seats').value)||1))));renderCalculator();});
  $$('[data-volume]').forEach(b=>b.addEventListener('click',()=>{$('#volume').value=String(volumes.indexOf(Number(b.dataset.volume)));renderCalculator();}));
  $$('[data-period]').forEach(b=>b.addEventListener('click',()=>{period=b.dataset.period;$$('[data-period]').forEach(other=>other.setAttribute('aria-pressed',String(other===b)));renderCalculator();}));renderCalculator();
  // Preserve the existing structured calculator capability.
  if(document.modelContext?.registerTool){const life=new AbortController();addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'set_lead_volume',title:'Estimate lead-list costs',description:'Set the visible calculator to a supported monthly lead volume and return the displayed estimates. Does not order or send contact information.',inputSchema:{type:'object',properties:{volume:{type:'integer',enum:volumes}},required:['volume'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!volumes.includes(input.volume))throw Error('Choose a supported monthly volume.');$('#volume').value=String(volumes.indexOf(input.volume));return renderCalculator();}},{signal:life.signal})).catch(()=>{});}catch{}}
})();
